import csv, json, re, hashlib, statistics as st
from collections import defaultdict
rows = list(csv.DictReader(open('data/scores.csv')))
tr = [json.loads(l) for l in open('data/judge_transcripts.jsonl')]
print(len(rows), len(tr))
print("sha256", hashlib.sha256(open('data/scores.csv','rb').read()).hexdigest())
byid = {t['rating_id']: t for t in tr}
mism = []
for r in rows:
    t = byid.get(r['rating_id'])
    if t is None:
        mism.append(('missing', r)); continue
    m = re.search(r'FINAL SCORE:\s*(\d+)', t['judge_output'])
    fs = int(m.group(1)) if m else None
    issues = []
    if fs != int(r['score']): issues.append(('score', fs, r['score']))
    if t['response_id'] != r['response_id']: issues.append('resp')
    if t['session'] != int(r['session']): issues.append(('session', t['session'], r['session']))
    if t['displayed_label'] != r['displayed_label']: issues.append(('label', t['displayed_label'], r['displayed_label']))
    m2 = re.search(r'Displayed author:\s*([\w-]+)', t['judge_output'])
    if m2 and m2.group(1) != t['displayed_label']: issues.append(('author_in_output', m2.group(1), t['displayed_label']))
    if issues: mism.append((r['rating_id'], issues))
print("mismatches:", len(mism))
for m in mism: print(m)
print("judge models:", set(t['judge_model'] for t in tr))
print("rating ids unique:", len(set(r['rating_id'] for r in rows)), len(rows))
# session/label pattern
print(defaultdict(int, {(r['session'], r['displayed_label']):0 for r in rows}))
c = defaultdict(int)
for r in rows: c[(r['session'], r['displayed_label'])]+=1
print(dict(c))
